'use strict';
/**
 * Password verification compatible with Werkzeug's `check_password_hash`, so an existing
 * ADMIN_PASSWORD_HASH generated by the Flask app keeps working unchanged.
 * Supported formats:  pbkdf2:<digest>:<iterations>$salt$hex   and   scrypt:<N>:<r>:<p>$salt$hex
 */
const crypto = require('crypto');
const config = require('../config');

const safeEqual = (a, b) => {
  const ab = Buffer.from(String(a));
  const bb = Buffer.from(String(b));
  return ab.length === bb.length && crypto.timingSafeEqual(ab, bb);
};

function checkWerkzeugHash(hash, password) {
  if (typeof hash !== 'string' || (hash.match(/\$/g) || []).length < 2) return false;
  const first = hash.indexOf('$');
  const second = hash.indexOf('$', first + 1);
  const method = hash.slice(0, first);
  const salt = hash.slice(first + 1, second);
  const expected = hash.slice(second + 1);
  const parts = method.split(':');
  try {
    if (parts[0] === 'scrypt') {
      const N = parseInt(parts[1], 10), r = parseInt(parts[2], 10), p = parseInt(parts[3], 10);
      const actual = crypto.scryptSync(password, salt, 64, { N, r, p, maxmem: 132 * N * r * p }).toString('hex');
      return safeEqual(actual, expected);
    }
    if (parts[0] === 'pbkdf2') {
      const digest = parts[1] || 'sha256';
      const iterations = parseInt(parts[2] || '1000000', 10);
      const keylen = crypto.createHash(digest).digest().length;
      const actual = crypto.pbkdf2Sync(password, salt, iterations, keylen, digest).toString('hex');
      return safeEqual(actual, expected);
    }
  } catch (_) {
    return false;
  }
  return false;
}

const sha = (s) => crypto.createHash('sha256').update(String(s)).digest('hex');

/**
 * Mirrors Config precedence from the Flask app:
 *   ADMIN_PASSWORD_HASH  >  ADMIN_PASSWORD (plain)  >  dev-only default "admin123".
 * The "admin123" fallback is disabled in production (no hard-coded credentials on a live site).
 */
function verifyAdminPassword(password) {
  if (config.ADMIN_PASSWORD_HASH) return checkWerkzeugHash(config.ADMIN_PASSWORD_HASH, password);
  if (config.ADMIN_PASSWORD) return safeEqual(sha(config.ADMIN_PASSWORD), sha(password));
  if (process.env.NODE_ENV !== 'production') return safeEqual(sha('admin123'), sha(password));
  return false;
}

module.exports = { checkWerkzeugHash, verifyAdminPassword };
